// Refresh the browser-safe country/calling-code catalog after updating phone metadata.
import {getCountries,getCountryCallingCode} from 'libphonenumber-js/max';
import {writeFile} from 'node:fs/promises';

const codes=Object.fromEntries(getCountries().sort().map(code=>[code,getCountryCallingCode(code)]));
await writeFile(new URL('../public/js/country-codes.js',import.meta.url),
  '// Generated by scripts/update-phone-countries.mjs from libphonenumber-js.\n'+
  'export const COUNTRY_CALLING_CODES=Object.freeze('+JSON.stringify(codes,null,2)+');\n');
